CREATE TABLE "permissions" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "key" TEXT NOT NULL, "description" TEXT NOT NULL, "reserved" BOOLEAN NOT NULL DEFAULT false, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "permissions_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "permissions_key_key" ON "permissions"("key");
CREATE TABLE "roles" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "name" TEXT NOT NULL, "key" TEXT NOT NULL, "city_id" UUID, "protected" BOOLEAN NOT NULL DEFAULT false, "active" BOOLEAN NOT NULL DEFAULT true, "description" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "roles_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "roles_key_city_id_key" ON "roles"("key","city_id"); CREATE INDEX "roles_city_id_active_idx" ON "roles"("city_id","active");
CREATE TABLE "role_permissions" ("role_id" UUID NOT NULL, "permission_id" UUID NOT NULL, CONSTRAINT "role_permissions_pkey" PRIMARY KEY ("role_id","permission_id"));
CREATE TABLE "user_role_assignments" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "user_id" UUID NOT NULL, "role_id" UUID NOT NULL, "approved_by_id" UUID, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "starts_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expires_at" TIMESTAMP(3), "reason" TEXT NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "user_role_assignments_pkey" PRIMARY KEY ("id"));
CREATE INDEX "user_role_assignments_user_id_status_expires_at_idx" ON "user_role_assignments"("user_id","status","expires_at");
CREATE TABLE "scope_grants" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "user_id" UUID NOT NULL, "scope_type" TEXT NOT NULL, "scope_id" UUID NOT NULL, "starts_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expires_at" TIMESTAMP(3), "reason" TEXT NOT NULL, CONSTRAINT "scope_grants_pkey" PRIMARY KEY ("id")); CREATE INDEX "scope_grants_user_id_scope_type_scope_id_idx" ON "scope_grants"("user_id","scope_type","scope_id");
CREATE TABLE "delegations" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "grantor_id" UUID NOT NULL, "delegatee_id" UUID NOT NULL, "permission" TEXT NOT NULL, "scope_type" TEXT, "scope_id" UUID, "starts_at" TIMESTAMP(3) NOT NULL, "expires_at" TIMESTAMP(3) NOT NULL, "revoked_at" TIMESTAMP(3), "reason" TEXT NOT NULL, CONSTRAINT "delegations_pkey" PRIMARY KEY ("id")); CREATE INDEX "delegations_delegatee_id_permission_starts_at_expires_at_idx" ON "delegations"("delegatee_id","permission","starts_at","expires_at");
CREATE TABLE "organization_units" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "name" TEXT NOT NULL, "unit_type" TEXT NOT NULL, "city_id" UUID, "parent_id" UUID, "active" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "organization_units_pkey" PRIMARY KEY ("id")); CREATE INDEX "organization_units_city_id_unit_type_active_idx" ON "organization_units"("city_id","unit_type","active");
CREATE TABLE "employment_profiles" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "user_id" UUID NOT NULL, "employee_number" TEXT, "designation" TEXT, "skills" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "shift" TEXT, "availability" TEXT NOT NULL DEFAULT 'AVAILABLE', "supervisor_id" UUID, "emergency_phone" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "employment_profiles_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "employment_profiles_user_id_key" ON "employment_profiles"("user_id"); CREATE UNIQUE INDEX "employment_profiles_employee_number_key" ON "employment_profiles"("employee_number");
ALTER TABLE "role_permissions" ADD CONSTRAINT "role_permissions_role_id_fkey" FOREIGN KEY ("role_id") REFERENCES "roles"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "role_permissions" ADD CONSTRAINT "role_permissions_permission_id_fkey" FOREIGN KEY ("permission_id") REFERENCES "permissions"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "user_role_assignments" ADD CONSTRAINT "user_role_assignments_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "user_role_assignments" ADD CONSTRAINT "user_role_assignments_role_id_fkey" FOREIGN KEY ("role_id") REFERENCES "roles"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "user_role_assignments" ADD CONSTRAINT "user_role_assignments_approved_by_id_fkey" FOREIGN KEY ("approved_by_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "scope_grants" ADD CONSTRAINT "scope_grants_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "delegations" ADD CONSTRAINT "delegations_grantor_id_fkey" FOREIGN KEY ("grantor_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "delegations" ADD CONSTRAINT "delegations_delegatee_id_fkey" FOREIGN KEY ("delegatee_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "organization_units" ADD CONSTRAINT "organization_units_parent_id_fkey" FOREIGN KEY ("parent_id") REFERENCES "organization_units"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "employment_profiles" ADD CONSTRAINT "employment_profiles_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
INSERT INTO "permissions" ("key","description","reserved") VALUES ('people.read','Read scoped workforce records',false),('people.invite','Invite workforce members',false),('people.status','Suspend or reactivate workforce members',false),('roles.read','Read role and permission definitions',false),('roles.manage','Create and assign protected roles',true),('audit.read','Read forensic audit records',true) ON CONFLICT ("key") DO NOTHING;
DO $$ DECLARE u RECORD; r UUID; BEGIN
  INSERT INTO roles (name,key,protected,description) VALUES ('Super Administrator','SUPER_ADMIN',true,'Protected platform administrator'),('City Administrator','CITY_ADMIN',true,'Protected city administrator'),('Commissioner','COMMISSIONER',true,'Protected commissioner'),('Zonal Officer','ZONAL_OFFICER',true,'Protected zonal officer'),('Department Head','DEPARTMENT_HEAD',true,'Protected department head'),('Ward Officer','WARD_OFFICER',true,'Protected ward officer'),('Field Worker','FIELD_WORKER',true,'Protected field worker'),('Citizen','CITIZEN',true,'Protected citizen') ON CONFLICT DO NOTHING;
  FOR u IN SELECT id,role FROM users LOOP SELECT id INTO r FROM roles WHERE key=u.role::text AND protected=true AND city_id IS NULL LIMIT 1; IF r IS NOT NULL THEN INSERT INTO user_role_assignments (user_id,role_id,approved_by_id,reason) VALUES (u.id,r,NULL,'M8 legacy role backfill') ON CONFLICT DO NOTHING; END IF; END LOOP;
END $$;
